 assert all(sha(ROOT/path)==value for path,value in baseline.items())
 reader=ROOT/'terminal/e2e/tools/optionsExposureEvidence.cjs'; before=reader.read_bytes()
 owner=ROOT/'terminal/lib/__tests__/optionsExposureEvidenceOwner.test.ts'; owner_before=owner.read_bytes()
 assert digest(before)=='70a3225e2b2bfa31499d818995368528c8a9ccf0bc9fae81e46756a3f2452122'
 assert digest(owner_before)=='6521af03a3ba257f796308e7d3b00a2ee57351b727da0a3a37c6fbb5806885cf'
 browser={}
 for stage,expected in [('joint',144),('expiry',9)]:
  directory=CAPTURE if stage=='joint' else CAPTURE/'expiry-journeys'
